// The field dump: the loaded table's records through its own
// accessors, each field with its host offset, in DWARF member order. A
// record class is dumped only when it is the type `getData` returns.
template <class Table>
void dump_table(Table& table) {
    if constexpr (ddon_is_table<Table>::value) {
        using Record = std::remove_cv_t<std::remove_pointer_t<decltype(table.getData(0u))>>;
        if constexpr (std::is_same_v<Record, ::cJumpParam>) {
            std::string out = "{\"record\":" + std::string("\"cJumpParam\"") + ",\"size\":" + std::to_string(sizeof(Record));
            auto count = table.getDataNum();
            out += ",\"count\":" + std::to_string(count) + ",\"records\":[";
            for (decltype(count) i = 0; i < count; ++i) {
                const Record* p = table.getData(i);
                out += i ? ",[" : "[";
                if (p) {
                    ddon_dump_field(out, "mSpeedY", p, p->mSpeedY);
                    out += ',';
                    ddon_dump_field(out, "mSpeedZ", p, p->mSpeedZ);
                    out += ',';
                    ddon_dump_field(out, "mGravity", p, p->mGravity);
                    out += ',';
                    ddon_dump_field(out, "mDampingZ", p, p->mDampingZ);
                    out += ',';
                    ddon_dump_field(out, "mAddMoveSpeedXZ", p, p->mAddMoveSpeedXZ);
                    out += ',';
                    ddon_dump_field(out, "mIsAwakening", p, p->mIsAwakening);
                    out += ',';
                    ddon_dump_field(out, "mAwakeJumpAdd", p, p->mAwakeJumpAdd);
                    out += ',';
                    ddon_dump_field(out, "mComment", p, p->mComment);
                }
                out += ']';
            }
            out += "]}";
            ddon_dump_append(out.data(), out.size());
        } else {
            const char none[] = "{\"record\":null}";
            ddon_dump_append(none, sizeof none - 1);
        }
    }
}
